sys_script_include.script:
function GetStakeholderRecord(vBusinessProcessOrStakeholder,vUser)
{
	var GetRecord = x_snc_devtools.GetRecord;
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var GetUserRecord = x_snc_devtools.GetUserRecord;

	var grStakeholder = GetRecord('x_snc_agenticbpc_stakeholder',vBusinessProcessOrStakeholder);
	if (IsValidRecord(grStakeholder) == true)
	{
		return grStakeholder;
	}

	var grBusinessProcess = GetBusinessProcessRecord(vBusinessProcessOrStakeholder);
	if (IsValidRecord(grBusinessProcess) == false)
	{
		return false;
	}

	var grUser = GetUserRecord(vUser);
	if (IsValidRecord(grUser) == false)
	{
		return false;
	}

	var grStakeholder = new GlideRecord('x_snc_agenticbpc_stakeholder');
	grStakeholder.addQuery('user','=',grUser.sys_id);
	grStakeholder.addQuery('business_process','=',grBusinessProcess.sys_id);
	grStakeholder.query();
	if (grStakeholder.getRowCount() != 1)
	{
		return false;
	}
	grStakeholder.next();
	return grStakeholder;

}
